bash -lc cat > /mnt/data/chatgpt_exporter_v2.js <<'EOF'
(() => {
  'use strict';
  const APP = 'nathan-chat-exporter-v2';
  const old = document.getElementById('local-chatgpt-conversation-exporter-panel');
  old?.remove();
  document.getElementById('local-chatgpt-conversation-exporter-button')?.remove();
  document.getElementById(APP)?.remove();
  document.getElementById(APP + '-button')?.remove();
  window.__nathanChatExporterLoaded = false;
  const escapeHtml = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const safeName = s => String(s || 'ChatGPT conversation').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').trim().slice(0,150);
  const id = () => location.pathname.match(/\/c\/([^/?#]+)/)?.[1];
  const iso = n => Number.isFinite(+n) && +n > 0 ? new Date(+n * 1000).toISOString() : null;
  const blobSize = s => new Blob([s]).size;
  const wait = ms => new Promise(r => setTimeout(r,ms));
  const download = (name, data, mime='text/plain;charset=utf-8') => {
    const url = URL.createObjectURL(data instanceof Blob ? data : new Blob([data],{type:mime}));
    const a = document.createElement('a'); a.href=url; a.download=name; document.body.append(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),30000);
  };
  async function request(url, token) {
    const r = await fetch(url,{credentials:'include',cache:'no-store',headers:{Accept:'application/json',...(token?{Authorization:'Bearer '+token}:{})}});
    return {ok:r.ok,status:r.status,data:await r.json().catch(()=>null)};
  }
  async function getConversation(){
    if(!id()) throw Error('Open an individual ChatGPT conversation first.');
    const url='/backend-api/conversation/'+encodeURIComponent(id());
    let r=await request(url);
    if(r.ok && r.data?.mapping) return r.data;
    const session=await request('/api/auth/session');
    const token=session.data?.accessToken || session.data?.access_token;
    if(token) r=await request(url,token);
    if(r.ok && r.data?.mapping) return r.data;
    throw Error('Conversation API unavailable (HTTP '+r.status+'). ChatGPT may have changed its private endpoint.');
  }
  function partText(p){
    if(p==null)return '';
    if(typeof p==='string')return p;
    if(Array.isArray(p))return p.map(partText).filter(Boolean).join('\n');
    if(typeof p==='object'){
      if(typeof p.text==='string')return p.text;
      if(typeof p.content==='string')return p.content;
      if(p.asset_pointer||p.image_asset_pointer||p.audio_asset_pointer||p.file_id)
        return '[Attachment: '+(p.content_type||p.type||'file')+' '+(p.asset_pointer||p.image_asset_pointer||p.audio_asset_pointer||p.file_id)+']';
      return '[Structured content]\n'+JSON.stringify(p,null,2);
    }
    return String(p);
  }
  function extract(conv, branch){
    const map=conv.mapping||{};
    let nodes=[];
    if(branch==='current' && conv.current_node && map[conv.current_node]){
      let key=conv.current_node; const seen=new Set();
      while(key && map[key] && !seen.has(key)){seen.add(key);nodes.push([key,map[key]]);key=map[key].parent;}
      nodes.reverse();
    } else {
      nodes=Object.entries(map).sort((a,b)=>(+a[1]?.message?.create_time||0)-(+b[1]?.message?.create_time||0));
    }
    return nodes.map(([nodeId,node])=>{
      const m=node.message;
      if(!m)return null;
      const content=m.content||{};
      const text=Array.isArray(content.parts)?content.parts.map(partText).filter(Boolean).join('\n'):
        typeof content.text==='string'?content.text:typeof content==='string'?content:partText(content);
      if(!text.trim())return null;
      return {node_id:nodeId,role:String(m.author?.role||'unknown'),author_name:m.author?.name||'',created_at:iso(m.create_time),updated_at:iso(m.update_time),text:text.trim(),metadata:m.metadata||{}};
    }).filter(Boolean);
  }
  const getDate = (d,end=false) => d ? new Date(d+(end?'T23:59:59.999':'T00:00:00')):null;
  function filter(messages,s){
    const from=getDate(s.start),to=getDate(s.end,true),needle=s.keyword.trim().toLocaleLowerCase();
    if(from && to && from>to)throw Error('Start date is after end date.');
    return messages.filter(m=>{
      if(!s.internal && !['user','assistant'].includes(m.role))return false;
      if(s.speaker!=='all' && m.role!==s.speaker)return false;
      if(needle && !m.text.toLocaleLowerCase().includes(needle))return false;
      if(from||to){if(!m.created_at)return false;const d=new Date(m.created_at);if(from&&d<from||to&&d>to)return false;}
      return true;
    }).map((m,i)=>({...m,sequence:i+1}));
  }
  function label(m){return m.role.toUpperCase()+(m.author_name?' · '+m.author_name:'');}
  function heading(m,s){return '['+m.sequence+'] '+label(m)+(s.timestamps&&m.created_at?' · '+m.created_at:'');}
  function meta(title,url,msgs,s){return {title,source_url:url,exported_at:new Date().toISOString(),message_count:msgs.length,settings:s};}
  function markdown(title,url,msgs,s){
    return ['# '+title,'','Source: '+url,'Exported: '+new Date().toISOString(),'Messages: '+msgs.length,'',...msgs.flatMap(m=>['## '+heading(m,s),'',m.text,'','---',''])].join('\n');
  }
  function plaintext(title,url,msgs,s){return [title,'Source: '+url,'Messages: '+msgs.length,'',...msgs.flatMap(m=>[heading(m,s),m.text,''])].join('\n\n');}
  function csvCell(v){return '"'+String(v??'').replace(/"/g,'""')+'"';}
  function csv(msgs,s){
    const cols=['sequence','role','author_name',...(s.timestamps?['created_at','updated_at']:[]),'text'];
    return [cols,...msgs.map(m=>cols.map(k=>m[k]??''))].map(row=>row.map(csvCell).join(',')).join('\r\n');
  }
  function json(title,url,msgs,s){
    return JSON.stringify({...meta(title,url,msgs,s),messages:msgs.map(m=>s.timestamps?m:(({created_at,updated_at,...rest})=>rest)(m))},null,2);
  }
  function texEscape(t){
    return String(t).replace(/[\\{}%$&#_^~]/g,c=>({'\\':'\\textbackslash{}','{':'\\{','}':'\\}','%':'\\%','$':'\\$','&':'\\&','#':'\\#','_':'\\_','^':'\\textasciicircum{}','~':'\\textasciitilde{}'}[c]));
  }
  function latex(title,url,msgs,s,revtex=false){
    const preamble=revtex ? '\\documentclass[aps,preprint,onecolumn]{revtex4-2}\n\\usepackage{fontspec}\n\\usepackage{hyperref}\n\\usepackage{fvextra}' :
